def validate(n: int) -> bool:
    """
    Check whether the frequency of each digit in n is <= the digit itself.

    Precondition (per contract):
        - n must be an integer
        - n >= 0
    """
    digit_counts = {}
    for ch in str(n):
        digit_counts[ch] = digit_counts.get(ch, 0) + 1

    for d_char, freq in digit_counts.items():
        if freq > int(d_char):
            return False

    return True
